ALTER TABLE public.services ADD COLUMN intervalo_retorno_dias integer NOT NULL DEFAULT 30 CHECK (intervalo_retorno_dias BETWEEN 1 AND 3650), ADD COLUMN regra_cliente text NOT NULL DEFAULT 'fixa' CHECK (regra_cliente IN ('fixa','progressiva')), ADD COLUMN intervalo_cliente_antiga_dias integer NOT NULL DEFAULT 90 CHECK (intervalo_cliente_antiga_dias BETWEEN 1 AND 3650);
CREATE FUNCTION public.service_return_defaults() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE n text:=translate(lower(NEW.name),'ãáàâéêíóôõúç','aaaaeeiooouc'); d integer:=30; BEGIN IF n ~ 'progressiva|botox|selagem' THEN NEW.regra_cliente:='progressiva'; d:=30; ELSIF n ~ 'mecha|luzes' THEN d:=60; ELSIF n ~ 'sobrancelha' THEN d:=15; ELSIF n ~ 'raiz|coloracao|tintura' THEN d:=20; ELSIF n ~ 'unha|mao|\mpe\M|alongamento|esmaltacao|manicure|pedicure' THEN d:=14; ELSIF n ~ 'corte' THEN d:=45; END IF; IF NEW.intervalo_retorno_dias=30 THEN NEW.intervalo_retorno_dias:=d; END IF; RETURN NEW; END $$;
CREATE TRIGGER service_return_default BEFORE INSERT ON public.services FOR EACH ROW EXECUTE FUNCTION public.service_return_defaults();
UPDATE public.services SET intervalo_retorno_dias=CASE WHEN translate(lower(name),'ãáàâéêíóôõúç','aaaaeeiooouc') ~ 'progressiva|botox|selagem' THEN 30 WHEN lower(name) ~ 'mecha|luzes' THEN 60 WHEN lower(name) ~ 'sobrancelha' THEN 15 WHEN translate(lower(name),'ãáàâéêíóôõúç','aaaaeeiooouc') ~ 'raiz|coloracao|tintura' THEN 20 WHEN translate(lower(name),'ãáàâéêíóôõúç','aaaaeeiooouc') ~ 'unha|mao|\mpe\M|alongamento|esmaltacao|manicure|pedicure' THEN 14 WHEN lower(name) ~ 'corte' THEN 45 ELSE 30 END, regra_cliente=CASE WHEN lower(name) ~ 'progressiva|botox|selagem' THEN 'progressiva' ELSE 'fixa' END;
CREATE TABLE public.imported_client_visits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.salons(id), client_id uuid NOT NULL REFERENCES public.salon_clients(id), service_id uuid NOT NULL REFERENCES public.services(id), visited_on date NOT NULL, source_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(salon_id,source_key));
GRANT SELECT ON public.imported_client_visits TO authenticated; GRANT ALL ON public.imported_client_visits TO service_role;
ALTER TABLE public.imported_client_visits ENABLE ROW LEVEL SECURITY;
CREATE POLICY imported_visits_manager ON public.imported_client_visits FOR SELECT TO authenticated USING(public.manages_salon(salon_id));
CREATE VIEW public.service_return_targets WITH (security_invoker=true) AS WITH history AS (SELECT salon_id,salon_client_id client_id,service_id,(starts_at AT TIME ZONE 'America/Sao_Paulo')::date visited_on FROM public.appointments WHERE status='finalizado' AND salon_client_id IS NOT NULL AND service_id IS NOT NULL UNION SELECT salon_id,client_id,service_id,visited_on FROM public.imported_client_visits), stats AS (SELECT salon_id,client_id,service_id,count(*) visits,min(visited_on) first_visit,max(visited_on) last_visit FROM history GROUP BY salon_id,client_id,service_id), rules AS (SELECT h.*,s.name service, CASE WHEN s.regra_cliente='progressiva' AND h.visits>3 AND h.last_visit>(h.first_visit+interval '3 months')::date THEN s.intervalo_cliente_antiga_dias ELSE s.intervalo_retorno_dias END interval_days FROM stats h JOIN public.services s ON s.id=h.service_id AND s.salon_id=h.salon_id) SELECT *,last_visit+interval_days next_return FROM rules;
GRANT SELECT ON public.service_return_targets TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.salon_crm_insights(_salon uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.manages_salon(_salon) THEN RAISE EXCEPTION 'Acesso restrito'; END IF; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'service',p.service,'visits',coalesce(p.visits,0),'last_visit',p.last_visit,'interval_days',p.interval_days,'days_away',(now() AT TIME ZONE 'America/Sao_Paulo')::date-p.last_visit,'needs_care',(now() AT TIME ZONE 'America/Sao_Paulo')::date>=p.next_return,'next_return',p.next_return,'due_this_week',p.next_return<=(date_trunc('week',now() AT TIME ZONE 'America/Sao_Paulo')::date+6) AND NOT EXISTS(SELECT 1 FROM public.appointments a WHERE a.salon_id=c.salon_id AND a.salon_client_id=c.id AND a.starts_at>now() AND a.status<>'cancelado'),'consent',c.consent) ORDER BY c.name) FROM public.salon_clients c LEFT JOIN LATERAL (SELECT * FROM public.service_return_targets t WHERE t.salon_id=c.salon_id AND t.client_id=c.id ORDER BY next_return,service_id LIMIT 1) p ON true WHERE c.salon_id=_salon),'[]'::jsonb); END $$;
CREATE FUNCTION public.prepare_service_returns(_salon uuid DEFAULT NULL, _manual boolean DEFAULT false) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN
UPDATE public.fila_mensagens_ia q SET status='cancelado',error='Retorno atualizado' WHERE (_salon IS NULL OR q.salon_id=_salon) AND q.tipo='cliente_sumida' AND q.status IN ('pendente','aguardando_conexao_whatsapp') AND NOT EXISTS(SELECT 1 FROM public.service_return_targets t WHERE t.salon_id=q.salon_id AND t.client_id=q.client_id AND q.dedupe_key='service-return:'||t.client_id||':'||t.service_id||':'||t.last_visit||':'||t.interval_days);
INSERT INTO public.fila_mensagens_ia(salon_id,client_id,dedupe_key,cliente_whatsapp,mensagem,tipo,status,agendado_para)
SELECT c.salon_id,c.id,'service-return:'||t.client_id||':'||t.service_id||':'||t.last_visit||':'||t.interval_days,c.whatsapp,'Oi, '||c.name||'! 💛 Já faz '||greatest((now() AT TIME ZONE 'America/Sao_Paulo')::date-t.last_visit,0)||' dias desde nosso cuidado com '||t.service||'. Que tal reservar um tempinho para você? Vamos consultar um horário com carinho? '||CASE WHEN translate(lower(t.service),'ãáàâéêíóôõúç','aaaaeeiooouc') ~ 'unha|mao|pe|alongamento|esmaltacao|manicure|pedicure' THEN '💅' ELSE '✨' END,'cliente_sumida','aguardando_conexao_whatsapp',CASE WHEN _manual AND t.next_return<=(now() AT TIME ZONE 'America/Sao_Paulo')::date THEN now() ELSE (t.next_return+time '09:00') AT TIME ZONE 'America/Sao_Paulo' END
FROM public.service_return_targets t JOIN public.salon_clients c ON c.id=t.client_id AND c.salon_id=t.salon_id LEFT JOIN public.salon_automation_preferences p ON p.salon_id=c.salon_id WHERE (_salon IS NULL OR c.salon_id=_salon) AND c.consent AND c.whatsapp<>'' AND public.salon_access_allowed(c.salon_id) AND coalesce(p.intelligent_return,true) AND (NOT _manual OR t.next_return<=date_trunc('week',now() AT TIME ZONE 'America/Sao_Paulo')::date+6) AND NOT EXISTS(SELECT 1 FROM public.appointments a WHERE a.salon_id=c.salon_id AND a.salon_client_id=c.id AND a.starts_at>now() AND a.status<>'cancelado') AND t.service_id=(SELECT x.service_id FROM public.service_return_targets x WHERE x.salon_id=t.salon_id AND x.client_id=t.client_id ORDER BY next_return,service_id LIMIT 1) ON CONFLICT(dedupe_key) DO NOTHING;
GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.prepare_service_returns(uuid,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.prepare_service_returns(uuid,boolean) TO service_role;
CREATE FUNCTION public.owner_prepare_service_returns(_salon uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.manages_salon(_salon) THEN RAISE EXCEPTION 'Acesso restrito'; END IF; RETURN public.prepare_service_returns(_salon,true); END $$;
REVOKE ALL ON FUNCTION public.owner_prepare_service_returns(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.owner_prepare_service_returns(uuid) TO authenticated;
CREATE FUNCTION public.import_salon_clients(_salon uuid,_rows jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; c uuid; s uuid; d date; p text; added integer:=0; reused integer:=0; v integer:=0; BEGIN IF NOT public.manages_salon(_salon) OR NOT public.salon_access_allowed(_salon) THEN RAISE EXCEPTION 'Acesso restrito'; END IF; IF jsonb_typeof(_rows)<>'array' OR jsonb_array_length(_rows)>100 THEN RAISE EXCEPTION 'Lote inválido'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(_salon::text,1)); FOR r IN SELECT value FROM jsonb_array_elements(_rows) LOOP
IF length(trim(r->>'name')) NOT BETWEEN 1 AND 200 OR length(trim(r->>'service')) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Nome ou serviço inválido'; END IF;
p:=regexp_replace(r->>'phone','[^0-9]','','g'); IF p !~ '^55[0-9]{10,11}$' THEN RAISE EXCEPTION 'Telefone inválido'; END IF; d:=(r->>'date')::date; IF d>(now() AT TIME ZONE 'America/Sao_Paulo')::date OR d<'1900-01-01'::date THEN RAISE EXCEPTION 'Data inválida'; END IF;
SELECT id INTO c FROM public.salon_clients WHERE salon_id=_salon AND (CASE WHEN length(regexp_replace(whatsapp,'[^0-9]','','g')) IN (10,11) THEN '55'||regexp_replace(whatsapp,'[^0-9]','','g') ELSE regexp_replace(whatsapp,'[^0-9]','','g') END)=p ORDER BY id LIMIT 1;
IF c IS NULL THEN INSERT INTO public.salon_clients(salon_id,name,whatsapp,consent) VALUES(_salon,trim(r->>'name'),p,false) RETURNING id INTO c; added:=added+1; ELSE reused:=reused+1; END IF;
SELECT id INTO s FROM public.services WHERE salon_id=_salon AND lower(trim(name))=lower(trim(r->>'service')) ORDER BY id LIMIT 1;
IF s IS NULL THEN INSERT INTO public.services(salon_id,name,price,duration_min) VALUES(_salon,trim(r->>'service'),0,60) RETURNING id INTO s; END IF;
INSERT INTO public.imported_client_visits(salon_id,client_id,service_id,visited_on,source_key) VALUES(_salon,c,s,d,c||':'||s||':'||d) ON CONFLICT(salon_id,source_key) DO NOTHING; GET DIAGNOSTICS v=ROW_COUNT;
UPDATE public.salon_clients SET last_visit=greatest(last_visit,(d+time '12:00') AT TIME ZONE 'America/Sao_Paulo') WHERE id=c AND salon_id=_salon;
END LOOP; PERFORM public.prepare_service_returns(_salon); RETURN jsonb_build_object('added',added,'reused',reused); END $$;
REVOKE ALL ON FUNCTION public.import_salon_clients(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.import_salon_clients(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.service_return_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.prepare_service_returns(coalesce(NEW.salon_id,OLD.salon_id)); RETURN coalesce(NEW,OLD); END $$;
CREATE TRIGGER return_history_change AFTER INSERT OR UPDATE OR DELETE ON public.imported_client_visits FOR EACH ROW EXECUTE FUNCTION public.service_return_change();
CREATE TRIGGER return_service_change AFTER UPDATE ON public.services FOR EACH ROW EXECUTE FUNCTION public.service_return_change();
DO $$ DECLARE def text; start_at integer; end_at integer; BEGIN SELECT pg_get_functiondef('public.prepare_evolving_messages(uuid)'::regprocedure) INTO def; start_at:=strpos(def,' INSERT INTO public.fila_mensagens_ia(salon_id,client_id,dedupe_key,cliente_whatsapp,mensagem,tipo,status,agendado_para)'); end_at:=strpos(def,'''birthday:'''); end_at:=strpos(substr(def,end_at), ' FROM public.salon_clients'); def:=regexp_replace(def,' INSERT INTO public.fila_mensagens_ia\(salon_id,client_id,dedupe_key,cliente_whatsapp,mensagem,tipo,status,agendado_para\)\s+SELECT c.salon_id,c.id,''care:.*?GET DIAGNOSTICS n=ROW_COUNT;total:=total\+n;', ' n:=public.prepare_service_returns(_salon); total:=total+n;', 's'); EXECUTE def; END $$;